import java.io.InputStream;
import java.io.IOException;
import java.util.PriorityQueue;
import java.util.Comparator;

public class Main {
    static class Item {
        int id;
        int type;
        int price;

        Item(int id, int type, int price) {
            this.id = id;
            this.type = type;
            this.price = price;
        }
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        private boolean hasNextByte() {
            if (ptr < len) return true;
            ptr = 0;
            try {
                len = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return len > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return res;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n == -1) return;
        int t = scanner.nextInt();

        int[] types = new int[n];
        for (int i = 0; i < n; i++) {
            types[i] = scanner.nextInt();
        }

        int[] prices = new int[n];
        for (int i = 0; i < n; i++) {
            prices[i] = scanner.nextInt();
        }

        int c = scanner.nextInt();
        int[] clients = new int[c];
        for (int i = 0; i < c; i++) {
            clients[i] = scanner.nextInt();
        }

        @SuppressWarnings("unchecked")
        PriorityQueue<Item>[] heapType = new PriorityQueue[t + 1];

        Comparator<Item> typeComp = (a, b) -> {
            if (a.price != b.price) {
                return Integer.compare(a.price, b.price);
            }
            return Integer.compare(a.id, b.id);
        };

        for (int i = 0; i < n; i++) {
            int type = types[i];
            if (heapType[type] == null) {
                heapType[type] = new PriorityQueue<>(typeComp);
            }
            heapType[type].add(new Item(i, type, prices[i]));
        }

        PriorityQueue<Item> globalHeap = new PriorityQueue<>((a, b) -> {
            if (a.price != b.price) {
                return Integer.compare(a.price, b.price);
            }
            if (a.type != b.type) {
                return Integer.compare(a.type, b.type);
            }
            return Integer.compare(a.id, b.id);
        });

        for (int i = 1; i <= t; i++) {
            if (heapType[i] != null && !heapType[i].isEmpty()) {
                globalHeap.add(heapType[i].peek());
            }
        }

        boolean[] sold = new boolean[n];
        long totalRevenue = 0;

        for (int i = 0; i < c; i++) {
            int u = clients[i];
            if (u > 0) {
                // Cliente decidido
                if (heapType[u] != null && !heapType[u].isEmpty()) {
                    Item bought = heapType[u].poll();
                    sold[bought.id] = true;
                    totalRevenue += bought.price;

                    if (!heapType[u].isEmpty()) {
                        globalHeap.add(heapType[u].peek());
                    }
                }
            } else {
                // Cliente indeciso
                while (!globalHeap.isEmpty()) {
                    Item cand = globalHeap.poll();
                    if (sold[cand.id]) {
                        continue;
                    }
                    sold[cand.id] = true;
                    totalRevenue += cand.price;

                    heapType[cand.type].poll();
                    if (!heapType[cand.type].isEmpty()) {
                        globalHeap.add(heapType[cand.type].peek());
                    }
                    break;
                }
            }
        }

        System.out.println(totalRevenue);
    }
}
